import AuthenticationServices
import CryptoKit
import Foundation
import SwiftUI

/// Why leaving for the identity provider's sign-in failed: the step, the
/// address and the status, as they were met.
public struct SignInError: Error, CustomStringConvertible {
    public let description: String
}

/// The identity provider of the specification's signIn (ADR-182): its
/// issuer and the app's client_id are the deployment's, which the app sets
/// at launch, as it sets the service's URL.
public enum IdentityProvider {
    /// The provider's issuer, the deployment's signIn.issuerUrl.
    @MainActor public static var issuerURL: URL? = nil
    /// The app's client_id, the deployment's clients.<client>.clientId.
    @MainActor public static var clientID = ""

    /// Signs in at the provider: OpenID Connect's authorisation code flow
    /// with PKCE's S256 method (RFC 7636), in the system's browser session,
    /// which hands back the redirect to the callback on the service's host;
    /// the callback is then called with its code and state, the state, the
    /// nonce and the PKCE verifier going with it in the __Host-sign-in
    /// cookie, which the callback reads, checks and clears. Throws a
    /// SignInError naming the step, the address and the status.
    @MainActor
    public static func signIn(callback: String, session: WebAuthenticationSession) async throws -> Answer {
        guard let issuer = issuerURL, !clientID.isEmpty else {
            throw SignInError(description: "the app gives no identity provider: set IdentityProvider.issuerURL and IdentityProvider.clientID at launch from the deployment's signIn.issuerUrl and the client's clientId")
        }
        let discoveryURL = issuer.appending(path: ".well-known/openid-configuration", directoryHint: .notDirectory)
        let (data, response) = try await URLSession.shared.data(from: discoveryURL)
        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
        guard status == 200, case .object(let discovery)? = JSON.parse(data) else {
            throw SignInError(description: "reading the provider's discovery document at \(discoveryURL.absoluteString) failed: HTTP \(status)")
        }
        guard case .string(let named)? = discovery["issuer"], named == issuer.absoluteString else {
            // OpenID Connect Discovery 1.0, 4.3: the issuer must be the one asked.
            throw SignInError(description: "the discovery document of \(issuer.absoluteString) names another issuer, and the two must be the same")
        }
        guard case .string(let endpoint)? = discovery["authorization_endpoint"], var components = URLComponents(string: endpoint),
              let host = Service.baseURL.host() else {
            throw SignInError(description: "the discovery document of \(issuer.absoluteString) names no authorization_endpoint, or the service's URL \(Service.baseURL.absoluteString) has no host")
        }
        let state = try random(), nonce = try random(), verifier = try random()
        let challenge = base64url(Data(SHA256.hash(data: Data(verifier.utf8))))
        let redirect = Service.baseURL.appending(path: callback, directoryHint: .notDirectory)
        if let cookie = HTTPCookie(properties: [.name: "__Host-sign-in", .value: "\(state).\(nonce).\(verifier)", .domain: host, .path: "/", .secure: "TRUE", .maximumAge: "600"]) {
            HTTPCookieStorage.shared.setCookie(cookie)
        }
        components.queryItems = [
            .init(name: "response_type", value: "code"), .init(name: "client_id", value: clientID),
            .init(name: "redirect_uri", value: redirect.absoluteString), .init(name: "scope", value: "openid"),
            .init(name: "state", value: state), .init(name: "nonce", value: nonce),
            .init(name: "code_challenge", value: challenge), .init(name: "code_challenge_method", value: "S256"),
        ]
        guard let url = components.url else {
            throw SignInError(description: "the authorization_endpoint \(endpoint) of \(issuer.absoluteString) is not a URL")
        }
        guard #available(iOS 17.4, macOS 14.4, *) else {
            throw SignInError(description: "the sign-in returns to the callback on https://\(host)\(redirect.path()), which needs iOS 17.4 or macOS 14.4")
        }
        // The redirect's own path, the service's path prefix included.
        let back = try await session.authenticate(using: url, callback: .https(host: host, path: redirect.path()), additionalHeaderFields: [:])
        let items = URLComponents(url: back, resolvingAgainstBaseURL: false)?.queryItems ?? []
        return try await Service.send("GET", callback, query: items.filter { $0.name == "code" || $0.name == "state" })
    }

    /// Signs in at the provider and, once the callback answers, reads the
    /// session again and opens the page sign-in was asked for from, or the
    /// app's first page. Answers nil when signed in, or the problem to show:
    /// the callback's status, or the step that failed.
    @MainActor
    public static func signInAndReturn(callback: String, session: WebAuthenticationSession, router: Router) async -> String? {
        do {
            let signedIn = try await signIn(callback: callback, session: session)
            if !(200..<400).contains(signedIn.status) {
                return "the callback \(callback) answered HTTP \(signedIn.status)"
            }
        } catch {
            return String(describing: error)
        }
        SessionStore.shared.forget()
        if let back = router.returnTo {
            router.returnTo = nil
            router.replace(with: back)
        } else {
            router.path = []
        }
        return nil
    }

    /// 32 random bytes, base64url without padding (RFC 7636, 4.1). Throws
    /// when the system gives none, since zero bytes would be a state, a
    /// nonce and a verifier anyone could guess.
    private static func random() throws -> String {
        var bytes = [UInt8](repeating: 0, count: 32)
        let status = SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes)
        guard status == errSecSuccess else {
            throw SignInError(description: "the system gave no random bytes for the state, the nonce and the PKCE verifier: SecRandomCopyBytes returned OSStatus \(status)")
        }
        return base64url(Data(bytes))
    }

    private static func base64url(_ data: Data) -> String {
        data.base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
    }
}
